package dev.localnotes;
import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.webkit.*;
import android.database.Cursor;
import android.provider.DocumentsContract;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class MainActivity extends Activity {
 AIService ai; final java.util.concurrent.ExecutorService network=java.util.concurrent.Executors.newSingleThreadExecutor();
 WebView web; Uri tree; JSONObject chooser; final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle state){super.onCreate(state);ai=new AIService(this);
  String saved=getPreferences(0).getString("tree",null);if(saved!=null)tree=Uri.parse(saved);
  try{File sample=new File(getFilesDir(),"Sample/Notes");if(!sample.exists()){sample.mkdirs();for(String filename:new String[]{"welcome.md","weekend.md"})try(InputStream in=getAssets().open("sample/Notes/"+filename);OutputStream out=new FileOutputStream(new File(sample,filename))){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}}catch(Exception e){throw new RuntimeException(e);}
  web=new WebView(this);web.setBackgroundColor(android.graphics.Color.WHITE);setContentView(web);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);
  web.addJavascriptInterface(new Bridge(),"NotesNative");web.setWebChromeClient(new WebChromeClient(){@Override public boolean onJsPrompt(WebView v,String u,String m,String d,JsPromptResult r){EditTextDialog(m,d,r);return true;}});
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("https://notes.local/");}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){String name=r.getUrl().getLastPathSegment();if(!r.getUrl().getHost().equals("notes.local")||!Arrays.asList("index.html","style.css","app.js","core.js","bridge.js","actions.js","action-screen.js", "initiatives.js", "initiative-screen.js", "library.js", "library-screen.js", "focus-screen.js", "revision-graph.js", "sync-screen.js", "organization.js", "organize-screen.js").contains(name))return new WebResourceResponse("text/plain","utf-8",new ByteArrayInputStream(new byte[0]));try{return new WebResourceResponse(name.endsWith(".js")?"text/javascript":name.endsWith(".css")?"text/css":"text/html","utf-8",getAssets().open("web/"+name));}catch(Exception e){return null;}}});web.loadUrl("https://notes.local/index.html");
 }
 void EditTextDialog(String message,String value,JsPromptResult result){android.widget.EditText input=new android.widget.EditText(this);input.setText(value);new AlertDialog.Builder(this).setMessage(message).setView(input).setPositiveButton("确定",(d,w)->result.confirm(input.getText().toString())).setNegativeButton("取消",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();}
 void reply(JSONObject req,JSONObject result){runOnUiThread(()->web.evaluateJavascript("window.nativeReply("+req.optInt("id")+","+result.toString()+")",null));}
 class Bridge{@JavascriptInterface public void request(String message){try{JSONObject req=new JSONObject(message);if(req.getString("cmd").equals("aiCancel")){ai.cancel();reply(req,new JSONObject());}else if(req.getString("cmd").equals("aiAnalyze")){final long ticket=ai.ticket();network.execute(()->{try{reply(req,ai.analyze(req,ticket));}catch(Exception e){reply(req,obj("error",e.getMessage()));}});}else if(req.getString("cmd").equals("choose")){runOnUiThread(()->{chooser=req;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,42);});}else worker.execute(()->{try{reply(req,run(req));}catch(Exception e){reply(req,obj("error",e.getMessage()==null?e.toString():e.getMessage()));}});}catch(Exception ignored){}}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=42||chooser==null)return;try{if(result!=RESULT_OK||data==null){reply(chooser,obj("cancelled",true));return;}Uri next=data.getData();String id=DocumentsContract.getTreeDocumentId(next);String last=id.substring(Math.max(id.lastIndexOf('/'),id.lastIndexOf(':'))+1);if(last.equalsIgnoreCase("credentials"))throw new IOException("不能将 Credentials 作为笔记目录");getContentResolver().takePersistableUriPermission(next,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));tree=next;getPreferences(0).edit().putString("tree",tree.toString()).apply();reply(chooser,new JSONObject());}catch(Exception e){reply(chooser,obj("error",e.getMessage()));}finally{chooser=null;}}
 static JSONObject obj(String k,Object v){JSONObject o=new JSONObject();try{o.put(k,v);}catch(Exception ignored){}return o;}
 void validate(String path)throws Exception{if(path.startsWith("/")||path.contains("\\")||!path.toLowerCase(Locale.ROOT).endsWith(".md"))throw new IOException("无效的笔记路径");for(String p:path.split("/",-1))if(p.isEmpty()||p.startsWith(".")||(p.equalsIgnoreCase("credentials")||p.equalsIgnoreCase("LocalNotesData")))throw new IOException("无效的笔记路径");}
 File local(String path)throws Exception{validate(path);File root=new File(getFilesDir(),"Sample");File f=new File(root,path);if(!f.getCanonicalPath().startsWith(root.getCanonicalPath()+"/"))throw new IOException("路径越界");return f;}
 Uri child(Uri parent,String name)throws Exception{Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(parent));try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c==null)throw new IOException("目录不可用");while(c.moveToNext())if(c.getString(1).equals(name))return DocumentsContract.buildDocumentUriUsingTree(tree,c.getString(0));}return null;}
 Uri resolve(String path,boolean create)throws Exception{validate(path);Uri p=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));String[] parts=path.split("/");for(int i=0;i<parts.length;i++){Uri next=child(p,parts[i]);if(next==null&&create)next=DocumentsContract.createDocument(getContentResolver(),p,i==parts.length-1?"text/markdown":DocumentsContract.Document.MIME_TYPE_DIR,parts[i]);if(next==null)throw new FileNotFoundException(path);p=next;}return p;}
 String read(String path)throws Exception{try(InputStream in=tree==null?new FileInputStream(local(path)):getContentResolver().openInputStream(resolve(path,false))){if(in==null)throw new IOException("无法读取文件");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>2000000)throw new IOException("笔记超过 2 MB");}return out.toString("UTF-8");}}
 boolean exists(String path)throws Exception{if(tree==null)return local(path).exists();try{resolve(path,false);return true;}catch(FileNotFoundException e){return false;}}
 void write(String path,String text)throws Exception{byte[] bytes=text.getBytes(StandardCharsets.UTF_8);if(tree==null){File f=local(path);f.getParentFile().mkdirs();android.util.AtomicFile atomic=new android.util.AtomicFile(f);FileOutputStream out=atomic.startWrite();try{out.write(bytes);atomic.finishWrite(out);}catch(Exception e){atomic.failWrite(out);throw e;}}else{Uri uri=resolve(path,true);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("无法写入文件");out.write(bytes);}if(!read(path).equals(text))throw new IOException("写入校验失败，请保留当前编辑");}}
 void snapshot(String text)throws Exception{File dir=new File(getFilesDir(),"History");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,UUID.randomUUID()+".md"))){out.write(text.getBytes(StandardCharsets.UTF_8));}File[] files=dir.listFiles();if(files!=null&&files.length>200){Arrays.sort(files,Comparator.comparingLong(File::lastModified).reversed());for(int i=200;i<files.length;i++)files[i].delete();}}
 void listLocal(File dir,String prefix,JSONArray notes)throws Exception{File[] files=dir.listFiles();if(files==null)throw new IOException("目录不可用");for(File f:files){if(f.getName().startsWith(".")||(f.getName().equalsIgnoreCase("credentials")||f.getName().equalsIgnoreCase("LocalNotesData")))continue;String p=prefix+f.getName();if(f.isDirectory())listLocal(f,p+"/",notes);else if(p.toLowerCase(Locale.ROOT).endsWith(".md")&&f.length()<=2000000)notes.put(new JSONObject().put("path",p).put("size",f.length()).put("modified",f.lastModified()/1000.0));}}
 void listTree(Uri parent,String prefix,JSONArray notes,int depth)throws Exception{if(depth>30)return;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(parent));try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_LAST_MODIFIED,DocumentsContract.Document.COLUMN_SIZE},null,null,null)){if(c==null)throw new IOException("目录不可用，请重新授权");while(c.moveToNext()){String name=c.getString(1);if(name.startsWith(".")||(name.equalsIgnoreCase("credentials")||name.equalsIgnoreCase("LocalNotesData")))continue;String path=prefix+name;Uri uri=DocumentsContract.buildDocumentUriUsingTree(tree,c.getString(0));if(DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2)))listTree(uri,path+"/",notes,depth+1);else if(name.toLowerCase(Locale.ROOT).endsWith(".md")&&c.getLong(4)<=2000000)notes.put(new JSONObject().put("path",path).put("size",c.getLong(4)).put("modified",c.getLong(3)/1000.0));}}}
 JSONObject run(JSONObject r)throws Exception{String cmd=r.getString("cmd"),path=r.optString("path");if(cmd.equals("aiSettings")||cmd.equals("aiConfigure"))return ai.configure(r);if(cmd.equals("workspace")||cmd.startsWith("action"))return new ActionStorage(this).run(r);if(!cmd.equals("choose")&&!r.optString("workspaceId").equals(new ActionStorage(this).workspace()))throw new IOException("Workspace changed; reopen the note");if(cmd.startsWith("reference"))return new ReferenceIndex(getFilesDir(),r.getString("workspaceId")).run(r);switch(cmd){case "metadata":case "list":JSONArray notes=new JSONArray();if(tree==null)listLocal(new File(getFilesDir(),"Sample"),"",notes);else listTree(DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree)),"",notes,0);return new JSONObject().put("notes",notes).put("root",tree==null?"Sample · 样本笔记":DocumentsContract.getTreeDocumentId(tree));case "read":return obj("text",read(path));case "create":if(exists(path))throw new IOException("目标文件已存在");write(path,r.getString("text"));return new JSONObject();case "save":case "move":String old=read(path);if(!old.equals(r.getString("expected")))throw new IOException("CONFLICT: 文件已被外部修改");snapshot(old);if(cmd.equals("move")){String target=r.getString("target");validate(target);if(exists(target))throw new IOException("目标文件已存在");write(target,old);if(!read(path).equals(old))throw new IOException("CONFLICT: 已保留副本，原文件发生修改");if(tree==null){if(!local(path).delete())throw new IOException("副本已创建，原文件未能移除");}else DocumentsContract.deleteDocument(getContentResolver(),resolve(path,false));}else{if(!read(path).equals(old))throw new IOException("CONFLICT");write(path,r.getString("text"));}return new JSONObject();default:throw new IOException("未知操作");}}
 @Override public void onBackPressed(){web.evaluateJavascript("document.querySelector('#back').click()",null);}
 @Override protected void onResume(){super.onResume();if(web!=null)web.evaluateJavascript("window.dispatchEvent(new Event('reference-change'))",null);}
 @Override protected void onPause(){web.evaluateJavascript("window.dispatchEvent(new Event('blur'))",null);super.onPause();}
}
